                type: 'code',
                language: 'ts',
                code: "import { createSerializeRegistry, jsonPlugin } from '@migaia/serialize'\nimport { createSSRStateScriptWith } from '@migaia/store-ssr'\nimport { openOrder } from './order-scope.ts'\nconst request = new Request('http://localhost/orders/1')\nconst codecs = createSerializeRegistry([jsonPlugin()])\nconst { scope } = openOrder(2)\ntry {\n  const html = await createSSRStateScriptWith(scope.dehydrate(), {\n    codecs,\n    elementId: 'order-state',\n    signal: request.signal\n  })\n  console.log(html)\n} finally {\n  await Promise.all([\n    scope.disposeAsync(),\n    codecs.dispose()\n  ])\n}"
