                language: 'ts',
                code: "import { createStore } from '@migaia/store-light'\n\nconst settings = createStore({ theme: 'light', fontSize: 14 })\nsettings.$set({ theme: 'dark', fontSize: 16 })\nconsole.log('Editor theme:', settings.theme)\nconsole.log('Editor font size:', settings.fontSize)\nawait settings.$dispose()"
