                type: 'code',
                language: 'ts',
                code: "import { streamBase64Chunks } from '@migaia/serialize/core'\n\nconst attachment = new Uint8Array([1, 2, 3, 4])\nfor (const part of streamBase64Chunks(attachment)) {\n  console.log('附件片段:', part)\n}"
