                type: 'code',
                language: 'ts',
                code: "import { createTray } from '@migaia/tray'\nimport { agent } from './agent.ts'\n\nconst tray = createTray({ hosts: [agent] })\ntry {\n  await tray.spawn('agent', { id: 'east' })\n  await tray.spawn('agent', { id: 'west' })\n  const price = tray.routing.roundRobin(agent)\n  for (const count of [2, 4]) {\n    const reply = await price.request('pricing.quote.subtotal', count)\n    console.log('计价实例:', reply.host, reply.total)\n  }\n} finally {\n  await tray.dispose()\n}"
